import java.io.*;
import java.util.*;
import java.text.*;
import java.lang.*;
import java.math.*;

public class Main {
    static BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter output = new PrintWriter(System.out);
    static long MOD_CONST = (long) 1e9 + 7;
    static long MOD_CONST1 = 998244353;

    public static void main(String[] args) throws Exception {
        long nVal = readNextLong();
        long mVal = readNextLong();
        long left = readNextLong();
        long right = readNextLong();

        long segmentSize = right - left + 1;
        long firstHalf = segmentSize / 2;
        long secondHalf = segmentSize - firstHalf;
        long totalCellsCount = nVal * mVal;

        long result;
        if (totalCellsCount % 2 == 1) {
            result = segmentSize % MOD_CONST;
        } else {
            long sumParts = (powerModulo(firstHalf + secondHalf, totalCellsCount, MOD_CONST) + powerModulo(Math.abs(firstHalf - secondHalf), totalCellsCount, MOD_CONST)) % MOD_CONST;
            result = (sumParts * modularInverse(2, MOD_CONST)) % MOD_CONST;
        }
        output.println(result);
        output.flush();
        output.close();
    }

    static long readNextLong() throws IOException {
        String[] parts = input.readLine().split(" ");
        return Long.parseLong(parts[0]);
    }

    static long powerModulo(long base, long exp, long mod) {
        long res = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long modularInverse(long a, long m) {
        return powerModulo(a, m - 2, m);
    }
}
